router.get('/backup/settings', async (_req, res) => {
  try {
    const item = await SystemInfo.findOne({ key: 'backup_settings' });
    const settings = item?.value ? JSON.parse(item.value) : {
      autoBackupEnabled: false,
      backupFolder: '',
