            <div class="field full"><span class="lbl">ملاحظات: </span><span class="val">${c?.notes || 'لا'}</span></div>
          </div>
        </div>
      `);
    }

    // بطاقات الإحصائيات
    const showStats = (exportSections.includes('fees') || exportSections.includes('expenses')) && s;
    if (showStats) {
      parts.push(`
        <div class="stats-row">
          <div class="stat-card navy">
            <div class="stat-num">${s?.totalCases || 0}</div>
            <div class="stat-lbl">القضايا</div>
          </div>
          <div class="stat-card navy">
            <div class="stat-num">${s?.totalSessions || 0}</div>
            <div class="stat-lbl">الجلسات</div>
          </div>
          <div class="stat-card navy">
            <div class="stat-num">${s?.totalAnnouncements || 0}</div>
            <div class="stat-lbl">الإعلانات</div>
          </div>
          <div class="stat-card gold">
            <div class="stat-num">${s?.totalFees || '0'}</div>
            <div class="stat-lbl">إجمالي الأتعاب (ج.م)</div>
          </div>
          <div class="stat-card green">
            <div class="stat-num">${s?.paidFees || '0'}</div>
            <div class="stat-lbl">المحصّل (ج.م)</div>
          </div>
          <div class="stat-card red">
            <div class="stat-num">${s?.remainingFees || '0'}</div>
            <div class="stat-lbl">المتبقي (ج.م)</div>
          </div>
        </div>
      `);
    }

    // القضايا
    if (exportSections.includes('cases') && dossier.cases?.length) {
      const rows = dossier.cases.map((c: any, i: number) => `
        <tr class="${i % 2 ? 'alt' : ''}"><td>${c.caseNumber || '—'}</td><td>${c.caseYear || '—'}</td><td>${c.courtName || '—'}</td><td>${c.caseTypeName || '—'}</td><td>${c.opponentName || '—'}</td><td>${c.clientRole || '—'}</td><td>${c.caseSubject || 'لا'}</td></tr>
      `).join('');
      parts.push(`
        <div class="sec-title">القضايا (${dossier.cases.length})</div>
        <table class="tbl"><thead><tr><th>رقم القضية</th><th>السنة</th><th>المحكمة</th><th>النوع</th><th>الخصم</th><th>صفة الموكل</th><th>الموضوع</th></tr></thead><tbody>${rows}</tbody></table>
      `);
    }

    // الجلسات
    if (exportSections.includes('sessions') && dossier.sessions?.length) {
      const rows = dossier.sessions.map((s: any, i: number) => `
        <tr class="${i % 2 ? 'alt' : ''}"><td>${s.sessionNumber || '—'}</td><td>${s.sessionDate || '—'}</td><td>${s.courtName || '—'}</td><td>${s.subject || '—'}</td><td>${s.sessionDecision || '—'}</td></tr>
      `).join('');
      parts.push(`
        <div class="sec-title">الجلسات (${dossier.sessions.length})</div>
        <table class="tbl"><thead><tr><th>رقم الجلسة</th><th>التاريخ</th><th>المحكمة</th><th>الموضوع</th><th>القرار</th></tr></thead><tbody>${rows}</tbody></table>
      `);
    }

    // الإعلانات
    if (exportSections.includes('announcements') && dossier.announcements?.length) {
      const rows = dossier.announcements.map((a: any, i: number) => `
        <tr class="${i % 2 ? 'alt' : ''}"><td>${a.announcementNumber || '—'}</td><td>${a.courtName || '—'}</td><td>${a.recipientName || '—'}</td><td>${a.subject || '—'}</td></tr>
      `).join('');
      parts.push(`
        <div class="sec-title">الإعلانات (${dossier.announcements.length})</div>
        <table class="tbl"><thead><tr><th>رقم الإعلان</th><th>المحكمة</th><th>المستلم</th><th>الموضوع</th></tr></thead><tbody>${rows}</tbody></table>
      `);
    }

    // اتفاقيات الاتعاب
    if (exportSections.includes('fees') && dossier.feeAgreements?.length) {
      const rows = dossier.feeAgreements.map((f: any, i: number) => `
        <tr class="${i % 2 ? 'alt' : ''}"><td>${f.caseNumber || '-'}</td><td>${f.totalAmount || '0'} ج.م</td><td>${f.paidAmount || '0'} ج.م</td><td>${f.remainingAmount || '0'} ج.م</td><td>${f.agreementDate || '—'}</td><td>${f.notes || 'لا'}</td></tr>
      `).join('');
      parts.push(`
        <div class="sec-title">اتفاقيات الأتعاب (${dossier.feeAgreements.length})</div>
        <table class="tbl"><thead><tr><th>رقم القضية</th><th>إجمالي الأتعاب</th><th>المدفوع</th><th>المتبقي</th><th>التاريخ</th><th>ملاحظات</th></tr></thead><tbody>${rows}</tbody></table>
      `);
    }

    // المصروفات
    if (exportSections.includes('expenses') && dossier.expenses?.length) {
      const rows = dossier.expenses.map((e: any, i: number) => `
        <tr class="${i % 2 ? 'alt' : ''}"><td>${e.caseNumber || '-'}</td><td>${e.category || '—'}</td><td>${e.amount || '—'} ج.م</td><td>${e.expenseDate || '—'}</td><td>${e.description || '—'}</td></tr>
      `).join('');
      parts.push(`
        <div class="sec-title">المصروفات (${dossier.expenses.length})</div>
        <table class="tbl"><thead><tr><th>رقم القضية</th><th>الفئة</th><th>المبلغ</th><th>التاريخ</th><th>الوصف</th></tr></thead><tbody>${rows}</tbody></table>
      `);
    }

    // المرفقات
    if (exportSections.includes('documents') && customerDocs.length) {
      const rows = customerDocs.map((d: any, i: number) => `
        <tr class="${i % 2 ? 'alt' : ''}"><td>${d.name || d.fileName || '—'}</td><td>${d.createdDate ? new Date(d.createdDate).toLocaleDateString('en-GB') : '—'}</td></tr>
      `).join('');
      parts.push(`
        <div class="sec-title">المرفقات (${customerDocs.length})</div>
        <table class="tbl"><thead><tr><th>اسم الملف</th><th>التاريخ</th></tr></thead><tbody>${rows}</tbody></table>
      `);
    }

    return `<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>ملف الموكل الشامل - ${dossier.customer?.name || ''}</title>
      <style>
        * { margin:0; padding:0; box-sizing:border-box; }
        body {
          font-family: 'Cairo', 'Tajawal', 'Segoe UI', Tahoma, Arial, sans-serif;
          padding: 40px;
          color: #000;
          font-size: 13px;
          line-height: 1.8;
        }
        .doc-title {
          font-size: 22px;
          font-weight: 700;
          color: #000;
          text-align: right;
        }
        .doc-date {
          font-size: 11px;
          color: #888;
          text-align: right;
          margin-bottom: 8px;
        }
        .divider {
          border: none;
          border-top: 2px solid #2c3e50;
          margin-bottom: 24px;
        }
        .sec-title {
          font-size: 15px;
          font-weight: 700;
          color: #000;
          margin: 28px 0 12px;
          text-align: right;
        }
        .info-box {
          background: #f5f5f5;
          border-radius: 6px;
          padding: 20px 24px;
        }
        .info-box .sec-title {
          margin-top: 0;
        }
        .info-grid {
          display: flex;
          flex-wrap: wrap;
          gap: 6px 40px;
        }
        .info-grid .field {
          font-size: 13px;
          color: #000;
          white-space: nowrap;
        }
        .info-grid .field .lbl {
          font-weight: 700;
        }
        .info-grid .field .val {
          font-weight: 400;
        }
        .info-grid .field.full {
          flex: 1 1 100%;
        }
        .stats-row {
          display: flex;
          gap: 10px;
          margin: 20px 0 24px;
          flex-wrap: wrap;
        }
        .stat-card {
          flex: 1;
          min-width: 90px;
          padding: 14px 10px;
          border-radius: 6px;
          text-align: center;
        }
        .stat-card.navy { background: #f0f3f7; border: 1px solid #d8dee8; }
        .stat-card.gold { background: #fdf8ed; border: 1px solid #e8d9b0; }
        .stat-card.green { background: #eef9f0; border: 1px solid #c8e8cc; }
        .stat-card.red { background: #fdf0f0; border: 1px solid #f0c8c8; }
        .stat-num {
          font-size: 18px;
          font-weight: 700;
          color: #000;
          margin-bottom: 4px;
        }
        .stat-card.gold .stat-num { color: #9a7d1e; }
        .stat-card.green .stat-num { color: #1a8a3e; }
        .stat-card.red .stat-num { color: #c0392b; }
        .stat-lbl {
          font-size: 11px;
          color: #666;
        }
        .tbl {
          width: 100%;
          border-collapse: collapse;
          margin-bottom: 16px;
        }
        .tbl th {
          background: #f5f5f5;
          font-weight: 700;
          font-size: 12px;
          padding: 8px 10px;
          text-align: right;
          border: 1px solid #ddd;
          color: #000;
        }
        .tbl td {
          padding: 6px 10px;
          font-size: 12px;
          text-align: right;
          border: 1px solid #ddd;
          color: #000;
        }
        .tbl tbody tr:nth-child(even) {
          background: #fafafa;
        }
        .doc-footer {
          margin-top: 40px;
          padding-top: 12px;
          border-top: 1px solid #ddd;
          text-align: center;
          font-size: 10px;
          color: #888;
        }
        @media print {
          body { padding: 24px; }
          .sec-title { page-break-after: avoid; }
          .tbl { page-break-inside: auto; }
          tr { page-break-inside: avoid; }
        }
      </style>
    </head><body>
      <div class="doc-title">ملف الموكل الشامل</div>
      <div class="doc-date">تاريخ التصدير: ${exportDate}</div>
      <hr class="divider">
      ${parts.join('')}
      <div class="doc-footer">LexPro — نظام إدارة مكاتب المحاماة</div>
    </body></html>`;
  };

  const printViaIframe = (html: string) => {
    const iframe = document.createElement('iframe');
    iframe.style.position = 'fixed';
    iframe.style.right = '0';
    iframe.style.bottom = '0';
    iframe.style.width = '0';
    iframe.style.height = '0';
    iframe.style.border = 'none';
    document.body.appendChild(iframe);

    const doc = iframe.contentWindow?.document;
    if (!doc) return;
    doc.open();
    doc.write(html);
    doc.close();

    iframe.onload = () => {
      try {
        iframe.contentWindow?.focus();
        iframe.contentWindow?.print();
      } catch {
        message.error('تعذر الطباعة');
      }
      setTimeout(() => document.body.removeChild(iframe), 1000);
    };
  };

  const handleExportPDF = async () => {
    if (!exportSections.length) { message.warning('اختر الأقسام المراد تصديرها'); return; }
    if (!dossier) return;

    const html = buildExportHTML();
    const fileName = `ملف-الموكل-${dossier.customer?.name || ''}.pdf`;

    if (window.electronAPI?.savePDF) {
      try {
        const result = await window.electronAPI.savePDF(html, fileName);
        if (result.success) {
          message.success('تم حفظ ملف PDF بنجاح');
        } else if (result.message !== 'تم إلغاء الحفظ') {
          message.error('تعذر حفظ الملف: ' + result.message);
        }
      } catch {
        message.error('حدث خطأ أثناء التصدير');
      }
    } else {
      printViaIframe(html);
    }
  };

  const handlePrint = async () => {
    if (!exportSections.length) { message.warning('اختر الأقسام المراد طباعتها'); return; }
    if (!dossier) return;

    const html = buildExportHTML();

    if (window.electronAPI?.printDocument) {
      try {
        const result = await window.electronAPI.printDocument(html);
        if (result.success) {
          message.success('تم إرسال المستند للطباعة');
        } else {
          message.error('تعذر الطباعة: ' + result.message);
        }
      } catch {
        message.error('حدث خطأ أثناء الطباعة');
      }
    } else {
      printViaIframe(html);
    }
  };

  const handleWhatsApp = () => {
    if (!exportSections.length) { message.warning('اختر الأقسام المراد إرسالها'); return; }
    const lines: string[] = ['*ملف الموكل الشامل*', ''];

    if (exportSections.includes('customer')) {
      const c = dossier.customer;
      lines.push('*بيانات الموكل*');
      lines.push(`الاسم: ${c?.name || '—'}`);
      lines.push(`الهاتف: ${c?.phone || '—'}`);
      if (c?.identityNumber) lines.push(`الرقم القومي: ${c.identityNumber}`);
      lines.push('');
    }

    if (exportSections.includes('cases') && dossier.cases?.length) {
      lines.push(`*القضايا (${dossier.cases.length})*`);
      dossier.cases.forEach((c: any, i: number) => {
        lines.push(`${i + 1}. ${c.caseNumber || ''} - ${c.opponentName || ''} - ${c.courtName || ''}`);
      });
      lines.push('');
    }

    if (exportSections.includes('sessions') && dossier.sessions?.length) {
      lines.push(`*الجلسات (${dossier.sessions.length})*`);
      dossier.sessions.forEach((s: any, i: number) => {
        lines.push(`${i + 1}. ${s.sessionDate || ''} - ${s.courtName || ''} - ${s.subject || ''}`);
      });
      lines.push('');
    }

    if (exportSections.includes('announcements') && dossier.announcements?.length) {
      lines.push(`*الإعلانات (${dossier.announcements.length})*`);
      dossier.announcements.forEach((a: any, i: number) => {
        lines.push(`${i + 1}. ${a.announcementNumber || ''} - ${a.courtName || ''} - ${a.recipientName || ''}`);
      });
      lines.push('');
    }

    if (exportSections.includes('fees') && dossier.feeAgreements?.length) {
      lines.push(`*الرسوم (${dossier.feeAgreements.length})*`);
      dossier.feeAgreements.forEach((f: any, i: number) => {
        lines.push(`${i + 1}. إجمالي: ${f.totalAmount || '0'} - مدفوع: ${f.paidAmount || '0'} - متبقي: ${f.remainingAmount || '0'}`);
      });
      lines.push('');
    }

    if (exportSections.includes('expenses') && dossier.expenses?.length) {
      lines.push(`*المصاريف (${dossier.expenses.length})*`);
      dossier.expenses.forEach((e: any, i: number) => {
        lines.push(`${i + 1}. ${e.amount || ''} - ${e.category || ''} - ${e.expenseDate || ''}`);
      });
      lines.push('');
    }

    if (exportSections.includes('documents') && customerDocs.length) {
      lines.push(`*المرفقات (${customerDocs.length})*`);
      customerDocs.forEach((d: any, i: number) => {
        lines.push(`${i + 1}. ${d.name || d.fileName || ''}`);
      });
      lines.push('');
    }

    const text = encodeURIComponent(lines.join('\n'));
    const phone = dossier.customer?.whatsappNumber?.replace(/[^0-9]/g, '') || '';
    const url = phone ? `https://wa.me/${phone}?text=${text}` : `https://wa.me/?text=${text}`;
    window.location.href = url;
  };

  const getFileType = (fileName: string): 'pdf' | 'image' | 'other' => {
    const ext = (fileName || '').split('.').pop()?.toLowerCase();
    if (ext === 'pdf') return 'pdf';
    if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'].includes(ext || '')) return 'image';
    return 'other';
  };

  const getFileIcon = (fileName: string) => {
    const type = getFileType(fileName);
    if (type === 'pdf') return <FilePdfOutlined style={{ fontSize: 20, color: '#c0392b' }} />;
    if (type === 'image') return <EyeOutlined style={{ fontSize: 20, color: '#2980b9' }} />;
    return <PaperClipOutlined style={{ fontSize: 20, color: '#C9A227' }} />;
  };

  const handleUploadDoc = async (file: File): Promise<boolean> => {
    if (!selectedCustomerId) return false;
    setUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      const uploadRes = await api.post('/files/upload', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      const fileId = uploadRes.data?.id || uploadRes.data?.fileId || uploadRes.data?._id;
      await api.post('/customer-documents', {
        customerId: selectedCustomerId,
        name: file.name,
        fileName: file.name,
        fileId,
      });
      message.success('تم رفع المرفق');
      fetchCustomerDocs(selectedCustomerId);
    } catch {
      message.error('تعذر رفع المرفق');
    } finally {
      setUploading(false);
    }
    return false;
  };

  const handleOpenDoc = (doc: any) => {
    const url = `${api.defaults.baseURL}/files/${doc.fileId}`;
    window.open(url, '_blank');
  };

  const handleDownloadDoc = (doc: any) => {
    const url = `${api.defaults.baseURL}/files/${doc.fileId}`;
    const a = document.createElement('a');
    a.href = url;
    a.download = doc.name || doc.fileName || 'file';
    a.target = '_blank';
    a.click();
  };

  const handleDeleteDoc = async (doc: any) => {
    try {
      await api.delete(`/customer-documents/${doc._id}`);
      message.success('تم حذف المرفق');
      fetchCustomerDocs(selectedCustomerId);
    } catch {
      message.error('تعذر حذف المرفق');
    }
  };

  const handleDocWhatsApp = (doc: any) => {
    const url = `${api.defaults.baseURL}/files/${doc.fileId}`;
    const text = encodeURIComponent(`*مرفق من ملف الموكل*\n${doc.name || doc.fileName || ''}\n${url}`);
    const phone = dossier?.customer?.whatsappNumber?.replace(/[^0-9]/g, '') || '';
    const waUrl = phone ? `https://wa.me/${phone}?text=${text}` : `https://wa.me/?text=${text}`;
    window.open(waUrl, '_blank');
  };

  const handleDocPrint = (doc: any) => {
    const type = getFileType(doc.name || doc.fileName || '');
    const url = `${api.defaults.baseURL}/files/${doc.fileId}`;
    if (type === 'pdf' || type === 'image') {
      const printWin = window.open(url, '_blank');
      if (printWin) {
        printWin.onload = () => { printWin.print(); };
      }
    } else {
      message.info('يمكن طباعة ملفات PDF والصور فقط');
    }
  };

  return (
    <div>
      <PageHeader
        title="ملف الموكل الشامل"
        subtitle="ابحث عن موكل لعرض كافة قضاياه وجلساته وإعلاناته وملفاته المالية في مكان واحد"
        searchValue={search}
        onSearch={setSearch}
        searchPlaceholder="ابحث باسم الموكل أو رقم الهاتف"
      />

      {!dossier && !dossierLoading && (
        <Card>
          <Space direction="vertical" style={{ width: '100%' }}>
            <Select
              showSearch
              placeholder="اختر موكل لعرض ملفه الشامل"
              style={{ width: '100%' }}
              optionFilterProp="children"
              onChange={loadDossier}
              options={filteredCustomers.map(c => ({ value: c._id, label: `${c.name} — ${c.phone}` }))}
            />
          </Space>
        </Card>
      )}

      {dossierLoading && (
        <div style={{ display: 'flex', justifyContent: 'center', padding: 80 }}>
          <Spin size="large" />
        </div>
      )}

      {dossier && (
        <div>
          <Card style={{ marginBottom: 10}} size="small">
            <Descriptions title={`بيانات الموكل: ${dossier.customer?.name}`} column={3} bordered size="small">
              <Descriptions.Item label="الاسم">{dossier.customer?.name}</Descriptions.Item>
              <Descriptions.Item label="الهاتف">{dossier.customer?.phone || '—'}</Descriptions.Item>
              <Descriptions.Item label="واتساب">{dossier.customer?.whatsappNumber || '—'}</Descriptions.Item>
              <Descriptions.Item label="البريد">{dossier.customer?.email || '—'}</Descriptions.Item>
              <Descriptions.Item label="الرقم القومي">{dossier.customer?.identityNumber || '—'}</Descriptions.Item>
              <Descriptions.Item label="العنوان">{dossier.customer?.address || '—'}</Descriptions.Item>
              <Descriptions.Item label="ملاحظات" span={3}>{dossier.customer?.notes || '—'}</Descriptions.Item>
            </Descriptions>
          </Card>

          <Row gutter={[12, 12]} style={{ marginBottom: 10 }}>
            <Col xs={12} sm={6}><Card size="small"><Statistic title="القضايا" value={dossier.stats?.totalCases || 0} /></Card></Col>
            <Col xs={12} sm={6}><Card size="small"><Statistic title="الجلسات" value={dossier.stats?.totalSessions || 0} /></Card></Col>
            <Col xs={12} sm={6}><Card size="small"><Statistic title="الإعلانات" value={dossier.stats?.totalAnnouncements || 0} /></Card></Col>
            <Col xs={12} sm={6}><Card size="small"><Statistic title="المصاريف" value={dossier.stats?.totalExpenses || 0} suffix="ج.م" /></Card></Col>
            <Col xs={12} sm={6}><Card size="small"><Statistic title="إجمالي الرسوم" value={dossier.stats?.totalFees || 0} suffix="ج.م" /></Card></Col>
            <Col xs={12} sm={6}><Card size="small"><Statistic title="المحصّل" value={dossier.stats?.paidFees || 0} suffix="ج.م" valueStyle={{ color: '#27ae60' }} /></Card></Col>
            <Col xs={12} sm={6}><Card size="small"><Statistic title="المتبقي" value={dossier.stats?.remainingFees || 0} suffix="ج.م" valueStyle={{ color: '#c0392b' }} /></Card></Col>
          </Row>

          <Tabs
            items={[
              {
                key: 'overview',
                label: 'نظرة عامة',
                children: (
                  <div>
                    <Card title={<span><ExportOutlined style={{ marginLeft: 8 }} />تصدير شامل</span>} size="small" style={{ marginBottom: 12 }}>
                      <Space direction="vertical" style={{ width: '100%' }} size="middle">
                        <Typography.Text strong>حدد الأقسام المراد تصديرها:</Typography.Text>
                        <Checkbox.Group
                          value={exportSections}
                          onChange={(vals) => setExportSections(vals as string[])}
                          options={sectionOptions}
                        />
                        <Divider style={{ margin: '4px 0' }} />
                        <Space wrap>
                          <Button type="primary" icon={<FilePdfOutlined />} onClick={handleExportPDF}>تصدير PDF</Button>
                          <Button icon={<PrinterOutlined />} onClick={handlePrint}>طباعة</Button>
                          <Button icon={<WhatsAppOutlined />} style={{ color: '#25D366', borderColor: '#25D366' }} onClick={handleWhatsApp}>واتساب</Button>
                        </Space>
                      </Space>
                    </Card>

                    <Row gutter={[12, 12]}>
                      <Col xs={12} sm={8}><Card size="small"><Statistic title="إجمالي القضايا" value={dossier.stats?.totalCases || 0} /></Card></Col>
                      <Col xs={12} sm={8}><Card size="small"><Statistic title="إجمالي الجلسات" value={dossier.stats?.totalSessions || 0} /></Card></Col>
                      <Col xs={12} sm={8}><Card size="small"><Statistic title="إجمالي الإعلانات" value={dossier.stats?.totalAnnouncements || 0} /></Card></Col>
                      <Col xs={12} sm={8}><Card size="small"><Statistic title="إجمالي الرسوم" value={dossier.stats?.totalFees || 0} suffix="ج.م" /></Card></Col>
                      <Col xs={12} sm={8}><Card size="small"><Statistic title="المحصّل" value={dossier.stats?.paidFees || 0} suffix="ج.م" valueStyle={{ color: '#27ae60' }} /></Card></Col>
                      <Col xs={12} sm={8}><Card size="small"><Statistic title="المتبقي" value={dossier.stats?.remainingFees || 0} suffix="ج.م" valueStyle={{ color: '#c0392b' }} /></Card></Col>
                    </Row>
                  </div>
                ),
              },
              { key: 'cases', label: `القضايا (${dossier.cases?.length || 0})`, children: <Table columns={caseColumns} dataSource={dossier.cases} rowKey="_id" pagination={{ pageSize: 5 }} size="small" /> },
              { key: 'sessions', label: `الجلسات (${dossier.sessions?.length || 0})`, children: <Table columns={sessionColumns} dataSource={dossier.sessions} rowKey="_id" pagination={{ pageSize: 5 }} size="small" /> },
              { key: 'announcements', label: `الإعلانات (${dossier.announcements?.length || 0})`, children: <Table columns={annColumns} dataSource={dossier.announcements} rowKey="_id" pagination={{ pageSize: 5 }} size="small" /> },
              { key: 'fees', label: `الرسوم (${dossier.feeAgreements?.length || 0})`, children: <Table columns={feeColumns} dataSource={dossier.feeAgreements} rowKey="_id" pagination={{ pageSize: 5 }} size="small" /> },
              { key: 'expenses', label: `المصاريف (${dossier.expenses?.length || 0})`, children: <Table columns={expenseColumns} dataSource={dossier.expenses} rowKey="_id" pagination={{ pageSize: 5 }} size="small" /> },
              {
                key: 'documents',
                label: `المرفقات (${customerDocs.length})`,
                children: (
                  <List
                    bordered
                    dataSource={customerDocs}
                    locale={{ emptyText: 'لا توجد مرفقات' }}
                    renderItem={(doc: any) => (
                      <List.Item
                        actions={[
                          <Button type="link" size="small" icon={<EyeOutlined />} onClick={() => handleOpenDoc(doc)} key="open">فتح</Button>,
                          <Button type="link" size="small" icon={<DownloadOutlined />} onClick={() => handleDownloadDoc(doc)} key="dl">تحميل</Button>,
                          <Button type="link" size="small" icon={<PrinterOutlined />} onClick={() => handleDocPrint(doc)} key="print">طباعة</Button>,
                          <Button type="link" size="small" style={{ color: '#25D366' }} icon={<WhatsAppOutlined />} onClick={() => handleDocWhatsApp(doc)} key="wa">واتساب</Button>,
                          <Popconfirm key="del" title="حذف هذا المرفق؟" onConfirm={() => handleDeleteDoc(doc)} okText="نعم" cancelText="لا">
                            <Button type="link" size="small" danger icon={<DeleteOutlined />}>حذف</Button>
                          </Popconfirm>,
                        ]}
                      >
                        <List.Item.Meta
                          avatar={getFileIcon(doc.name || doc.fileName || '')}
                          title={doc.name || doc.fileName || 'ملف بدون اسم'}
                          description={doc.createdDate ? new Date(doc.createdDate).toLocaleDateString('ar-EG') : ''}
                        />
                      </List.Item>
                    )}
                  />
                ),
              },
            ]}
          />
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Tabs, Table, Modal, Form, Input, Button, Card, Descriptions, Space, Upload, message, Spin, Typography, Row, Col, Select, Popconfirm } from 'antd';
import { UploadOutlined, PlusOutlined, DownloadOutlined, DeleteOutlined, ArrowRightOutlined, CalendarOutlined, FileTextOutlined } from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';
import { AppModal } from '../components/AppModal';

const { Title } = Typography;

const casesApi = createCrudApi('/cases');
const sessionsApi = createCrudApi('/sessions');
const caseDocsApi = createCrudApi('/case-documents');
const announcementsApi = createCrudApi('/announcements');
const feesApi = createCrudApi('/fees');
const expensesApi = createCrudApi('/expenses');
const courtsApi = createCrudApi('/courts');

export default function CaseDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [caseData, setCaseData] = useState<any>(null);
  const [sessions, setSessions] = useState<any[]>([]);
  const [documents, setDocuments] = useState<any[]>([]);
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [fees, setFees] = useState<any[]>([]);
  const [expenses, setExpenses] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [sessionModalOpen, setSessionModalOpen] = useState(false);
  const [sessionForm] = Form.useForm();
  const [docModalOpen, setDocModalOpen] = useState(false);
  const [docForm] = Form.useForm();
  const [uploading, setUploading] = useState(false);

  const fetchData = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try {
      const [caseRes, sessRes, docsRes, annRes, feeRes, expRes, courtsRes] = await Promise.all([
        casesApi.getById(id),
        sessionsApi.getAll(),
        caseDocsApi.getAll(),
        announcementsApi.getAll(),
        feesApi.getAll(),
        expensesApi.getAll(),
        courtsApi.getAll(),
      ]);
      setCaseData(caseRes.data.data || caseRes.data);
      const allSessions = sessRes.data.data || sessRes.data || [];
      setSessions(allSessions.filter((s: any) => s.caseId === id || s.caseId?._id === id));
      const allDocs = docsRes.data.data || docsRes.data || [];
      setDocuments(allDocs.filter((d: any) => d.caseId === id || d.caseId?._id === id));
      const allAnn = annRes.data.data || annRes.data || [];
      setAnnouncements(allAnn.filter((a: any) => a.caseId === id || a.caseId?._id === id));
      const allFees = feeRes.data.data || feeRes.data || [];
      setFees(allFees.filter((f: any) => f.caseId === id || f.caseId?._id === id));
      const allExp = expRes.data.data || expRes.data || [];
      setExpenses(allExp.filter((e: any) => e.caseId === id || e.caseId?._id === id));
      setCourts(courtsRes.data.data || courtsRes.data || []);
    } catch { message.error('حدث خطأ أثناء تحميل بيانات القضية'); }
    finally { setLoading(false); }
  }, [id]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleAddSession = async () => {
    try {
      const values = await sessionForm.validateFields();
      await sessionsApi.create({ ...values, caseId: id });
      message.success('تم إضافة الجلسة');
      setSessionModalOpen(false);
      sessionForm.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
  };

  const handleUploadDoc = async () => {
    try {
      const values = await docForm.validateFields();
      const file = values.file?.[0]?.originFileObj || values.file;
      if (!file) { message.error('يرجى اختيار ملف'); return; }
      setUploading(true);
      const uploadRes = await fileApi.upload(file);
      const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
      const fileName = uploadRes.data.data?.fileName || file.name;
      await caseDocsApi.create({ caseId: id, documentName: values.documentName, documentType: values.documentType || '', fileId, fileName, notes: values.notes || '' });
      message.success('تم رفع المستند');
      setDocModalOpen(false);
      docForm.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ أثناء الرفع'); }
    finally { setUploading(false); }
  };

  const handleDeleteDoc = async (docId: string) => {
    try { await caseDocsApi.delete(docId); message.success('تم حذف المستند'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const handleDeleteSession = async (sid: string) => {
    try { await sessionsApi.delete(sid); message.success('تم حذف الجلسة'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  if (loading) return <Spin size="large" style={{ display: 'flex', justifyContent: 'center', marginTop: 100 }} />;
  if (!caseData) return <div>القضية غير موجودة</div>;

  const sessionColumns = [
    { title: 'الجلسة #', dataIndex: 'sessionNumber' },
    { title: 'التاريخ', dataIndex: 'sessionDate' },
    { title: 'الموضوع', dataIndex: 'subject' },
    { title: 'النوع', dataIndex: 'sessionType' },
    { title: 'القرار', dataIndex: 'sessionDecision', ellipsis: true },
    { title: 'الجلسة القادمة', dataIndex: 'nextSessionDate' },
    { title: 'إجراءات', render: (_: any, r: any) => <Popconfirm title="حذف الجلسة؟" onConfirm={() => handleDeleteSession(r._id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm> },
  ];

  const docColumns = [
    { title: 'اسم المستند', dataIndex: 'documentName' },
    { title: 'النوع', dataIndex: 'documentType' },
    { title: 'التاريخ', dataIndex: 'createdDate' },
    {
      title: 'إجراءات', render: (_: any, r: any) => (
        <Space>
          <Button type="link" icon={<DownloadOutlined />} href={fileApi.getUrl(r.fileId)} target="_blank">تحميل</Button>
          <Popconfirm title="حذف المستند؟" onConfirm={() => handleDeleteDoc(r._id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>
        </Space>
      ),
    },
  ];

  const annColumns = [
    { title: 'رقم الإعلان', dataIndex: 'announcementNumber' },
    { title: 'المستلم', dataIndex: 'recipientName' },
    { title: 'الموضوع', dataIndex: 'subject', ellipsis: true },
    { title: 'المحضر', dataIndex: 'bailiffName' },
    { title: 'تاريخ التسليم', dataIndex: 'deliveryDate' },
  ];

  const feeColumns = [
    { title: 'العميل', dataIndex: 'customerName' },
    { title: 'المبلغ الإجمالي', dataIndex: 'totalAmount' },
    { title: 'المدفوع', dataIndex: 'paidAmount' },
    { title: 'المتبقي', dataIndex: 'remainingAmount' },
    { title: 'التاريخ', dataIndex: 'agreementDate' },
  ];

  const expColumns = [
    { title: 'التاريخ', dataIndex: 'expenseDate' },
    { title: 'الوصف', dataIndex: 'description' },
    { title: 'الفئة', dataIndex: 'category' },
    { title: 'المبلغ', dataIndex: 'amount' },
  ];

  return (
    <div>
      <Button icon={<ArrowRightOutlined />} onClick={() => navigate('/cases')} style={{ marginBottom: 10 }}>العودة للقضايا</Button>
      <Card style={{ marginBottom: 10 }} size="small">
        <Descriptions title={`القضية رقم ${caseData.caseNumber} - ${caseData.caseYear}`} bordered column={2} size="small">
          <Descriptions.Item label="العميل">{caseData.customerName || caseData.customerId?.name}</Descriptions.Item>
          <Descriptions.Item label="الخصم">{caseData.opponentName}</Descriptions.Item>
          <Descriptions.Item label="المحكمة">{caseData.courtName || caseData.courtId?.name}</Descriptions.Item>
          <Descriptions.Item label="نوع القضية">{caseData.caseTypeName || caseData.caseTypeId?.name}</Descriptions.Item>
          <Descriptions.Item label="رقم الدائرة">{caseData.circuitNumber}</Descriptions.Item>
          <Descriptions.Item label="الموضوع">{caseData.caseSubject}</Descriptions.Item>
          <Descriptions.Item label="صفة الموكل">{caseData.clientCapacity}</Descriptions.Item>
          <Descriptions.Item label="صفة الخصم">{caseData.opponentCapacity}</Descriptions.Item>
        </Descriptions>
      </Card>
      <Tabs items={[
        { key: 'sessions', label: 'الجلسات', children: (
          <div>
            <Button type="primary" size="small" icon={<PlusOutlined />} onClick={() => setSessionModalOpen(true)} style={{ marginBottom: 10 }}>إضافة جلسة</Button>
            <Table columns={sessionColumns} dataSource={sessions} rowKey="_id" size="small" pagination={{ pageSize: 5 }} />
          </div>
        )},
        { key: 'docs', label: 'المستندات', children: (
          <div>
            <Button type="primary" size="small" icon={<PlusOutlined />} onClick={() => setDocModalOpen(true)} style={{ marginBottom: 10 }}>رفع مستند</Button>
            <Table columns={docColumns} dataSource={documents} rowKey="_id" size="small" pagination={{ pageSize: 5 }} />
          </div>
        )},
        { key: 'announcements', label: 'الإعلانات', children: <Table columns={annColumns} dataSource={announcements} rowKey="_id" size="small" pagination={{ pageSize: 5 }} /> },
        { key: 'fees', label: 'الرسوم', children: <Table columns={feeColumns} dataSource={fees} rowKey="_id" size="small" pagination={{ pageSize: 5 }} onRow={(r) => ({ onClick: () => navigate(`/fees/${r._id}`), style: { cursor: 'pointer' } })} /> },
        { key: 'expenses', label: 'المصاريف', children: <Table columns={expColumns} dataSource={expenses} rowKey="_id" size="small" pagination={{ pageSize: 5 }} /> },
      ]} />

      <AppModal
        title="إضافة جلسة"
        subtitle="إضافة جلسة جديدة للقضية"
        icon={<CalendarOutlined />}
        iconColor="#2980b9"
        iconColorTo="#3498db"
        open={sessionModalOpen}
        onOk={handleAddSession}
        onCancel={() => setSessionModalOpen(false)}
        okText="حفظ"
        cancelText="إلغاء"
        width={640}
      >
        <Form form={sessionForm} layout="vertical">
          <Row gutter={16}>
            <Col span={12}><Form.Item name="sessionNumber" label="رقم الجلسة" rules={[{ required: true }]}><Input type="number" /></Form.Item></Col>
            <Col span={12}><Form.Item name="sessionDate" label="تاريخ الجلسة" rules={[{ required: true }]}><Input type="date" /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="courtId" label="المحكمة" rules={[{ required: true }]}><Select options={courts.map((c: any) => ({ value: c._id, label: c.name }))} /></Form.Item></Col>
            <Col span={12}><Form.Item name="rollNumber" label="رقم الدور"><Input /></Form.Item></Col>
          </Row>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="hallNumber" label="رقم القاعة"><Input /></Form.Item></Col>
            <Col span={12}><Form.Item name="sessionType" label="نوع الجلسة"><Input /></Form.Item></Col>
          </Row>
          <Form.Item name="subject" label="الموضوع" rules={[{ required: true }]}><Input /></Form.Item>
          <Form.Item name="sessionDecision" label="القرار" rules={[{ required: true }]}><Input.TextArea rows={2} /></Form.Item>
          <Row gutter={16}>
            <Col span={12}><Form.Item name="nextSessionDate" label="الجلسة القادمة"><Input type="date" /></Form.Item></Col>
          </Row>
          <Form.Item name="notes" label="ملاحظات" rules={[{ required: true }]}><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </AppModal>

      <AppModal
        title="رفع مستند"
        subtitle="رفع مستند مرتبط بالقضية"
        icon={<FileTextOutlined />}
        iconColor="#C9A227"
        iconColorTo="#e0b53e"
        open={docModalOpen}
        onOk={handleUploadDoc}
        onCancel={() => setDocModalOpen(false)}
        confirmLoading={uploading}
        okText="رفع"
        cancelText="إلغاء"
        width={560}
      >
        <Form form={docForm} layout="vertical">
          <Form.Item name="documentName" label="اسم المستند" rules={[{ required: true }]}><Input placeholder="اسم المستند" /></Form.Item>
          <Form.Item name="documentType" label="نوع المستند"><Input placeholder="نوع المستند" /></Form.Item>
          <Form.Item name="file" label="الملف" rules={[{ required: true }]} valuePropName="fileList" getValueFromEvent={e => Array.isArray(e) ? e : e?.fileList}>
            <Upload beforeUpload={() => false} maxCount={1}><Button icon={<UploadOutlined />}>اختيار ملف</Button></Upload>
          </Form.Item>
          <Form.Item name="notes" label="ملاحظات"><Input.TextArea rows={2} /></Form.Item>
        </Form>
      </AppModal>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Table, Button, Modal, Form, Input, Select, Space, Popconfirm, message, Row, Col, Upload, Typography } from 'antd';
import type { UploadFile } from 'antd/es/upload/interface';
import {
  EditOutlined, DeleteOutlined, UploadOutlined, PaperClipOutlined,
  SaveOutlined, FolderOpenOutlined, TeamOutlined, FileTextOutlined,
  CalendarOutlined, NotificationOutlined, UserOutlined, EnvironmentOutlined,
} from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';
import { PageHeader } from '../components/PageHeader';
import { AppModal, FormSection } from '../components/AppModal';

const { Title, Text } = Typography;

const announcementsApi = createCrudApi('/announcements');
const casesApi = createCrudApi('/cases');
const courtsApi = createCrudApi('/courts');
const annTypesApi = createCrudApi('/announcement-types');
const customersApi = createCrudApi('/customers');
const annDocsApi = createCrudApi('/announcement-documents');

export default function Announcements() {
  const [data, setData] = useState<any[]>([]);
  const [cases, setCases] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [annTypes, setAnnTypes] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [customerFilter, setCustomerFilter] = useState<string | undefined>(undefined);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | undefined>(undefined);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);
  const [fileList, setFileList] = useState<UploadFile[]>([]);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [annRes, caseRes, courtRes, typeRes, custRes] = await Promise.all([
        announcementsApi.getAll(), casesApi.getAll(), courtsApi.getAll(),
        annTypesApi.getAll(), customersApi.getAll(),
      ]);
      setData(annRes.data.data || annRes.data || []);
      setCases(caseRes.data.data || caseRes.data || []);
      setCourts(courtRes.data.data || courtRes.data || []);
      setAnnTypes(typeRes.data.data || typeRes.data || []);
      setCustomers(custRes.data.data || custRes.data || []);
    } catch { message.error('حدث خطأ'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  // دالة مساعدة: استخراج customerId نصي من القضية (قد يكون object بعد populate)
  const getCaseCustomerId = (c: any): string | undefined => {
    if (!c?.customerId) return undefined;
    return typeof c.customerId === 'object' ? c.customerId?._id : c.customerId;
  };

  // خريطة: caseId → customerId (نصي)
  const caseCustomerMap = new Map<string, string>();
  cases.forEach((c: any) => {
    const custId = getCaseCustomerId(c);
    if (custId) caseCustomerMap.set(c._id, custId);
  });

  // خريطة: customerId → customerName
  const customerNameMap = new Map<string, string>(
    customers.map((c: any) => [c._id, c.name])
  );

  // دالة مساعدة: جلب اسم الموكل من إعلان
  const getCustomerName = (a: any): string => {
    const caseId = typeof a.caseId === 'object' ? a.caseId?._id : a.caseId;
    const custId = caseCustomerMap.get(caseId);
    return custId ? (customerNameMap.get(custId) || '') : '';
  };

  const filtered = data.filter((a: any) => {
    if (customerFilter) {
      const caseId = typeof a.caseId === 'object' ? a.caseId?._id : a.caseId;
      const custId = caseCustomerMap.get(caseId);
      if (custId !== customerFilter) return false;
    }
    if (!search) return true;
    const q = search.toLowerCase();
    const custName = getCustomerName(a).toLowerCase();
    return (
      (a.announcementNumber || '').includes(q) ||
      (a.caseNumber || '').includes(q) ||
      (a.recipientName || '').toLowerCase().includes(q) ||
      custName.includes(q)
    );
  });

  const openModal = (record?: any) => {
    setEditing(record || null);
    setFileList([]);
    if (record) {
      const caseId = typeof record.caseId === 'object' ? record.caseId?._id : record.caseId;
      // استخراج customerId من القضية المرتبطة
      const custId = caseId ? caseCustomerMap.get(caseId) : undefined;
      setSelectedCustomerId(custId);
      form.setFieldsValue({ ...record, caseId, customerId: custId });
    } else {
      setSelectedCustomerId(undefined);
      form.resetFields();
    }
    setModalOpen(true);
  };

  // تصفية القضايا حسب الموكل المختار داخل النافذة
  const filteredCases = selectedCustomerId
    ? cases.filter((c: any) => getCaseCustomerId(c) === selectedCustomerId)
    : cases;

  // عند تغيير القضية في النافذة، تحديث الموكل تلقائياً
  const handleCaseChange = (caseId: string) => {
    const custId = caseId ? caseCustomerMap.get(caseId) : undefined;
    setSelectedCustomerId(custId);
    form.setFieldsValue({ customerId: custId });
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setSubmitting(true);
      let announcementId: string;

      if (editing?._id) {
        await announcementsApi.update(editing._id, values);
        announcementId = editing._id;
        message.success('تم تحديث الإعلان');
      } else {
        const res = await announcementsApi.create(values);
        announcementId = res.data.data?._id || res.data._id;
        message.success('تمت إضافة الإعلان');
      }

      // رفع المرفقات
      if (fileList.length > 0 && announcementId) {
        for (const file of fileList) {
          const rawFile = file.originFileObj;
          if (!rawFile) continue;
          const uploadRes = await fileApi.upload(rawFile);
          const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
          const fileName = uploadRes.data.data?.fileName || rawFile.name;
          await annDocsApi.create({
            caseAnnouncementId: announcementId,
            documentName: rawFile.name,
            documentType: 'مرفق',
            fileId,
            fileName,
          });
        }
        message.success(`تم رفع ${fileList.length} مرفق`);
      }

      setModalOpen(false);
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = async (id: string) => {
    try { await announcementsApi.delete(id); message.success('تم الحذف'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const columns = [
    { title: 'رقم الإعلان', dataIndex: 'announcementNumber', width: 80 },
    { title: 'رقم القضية', dataIndex: 'caseNumber', width: 80 },
    { title: 'الموكل', width: 100, ellipsis: true, render: (_: any, r: any) => getCustomerName(r) || '-' },
    { title: 'المحكمة', dataIndex: 'courtName', ellipsis: true },
    { title: 'النوع', dataIndex: 'announcementTypeName', ellipsis: true },
    { title: 'المستلم', dataIndex: 'recipientName', ellipsis: true },
    { title: 'الموضوع', dataIndex: 'subject', ellipsis: true },
    { title: 'المحضر', dataIndex: 'bailiffName', ellipsis: true },
    { title: 'تاريخ التسليم', dataIndex: 'deliveryDate', width: 100 },
    { title: 'تاريخ الاستلام', dataIndex: 'receiptDate', width: 100 },
    { title: 'إجراءات', width: 70, render: (_: any, r: any) => (
      <Space>
        <Button type="text" icon={<EditOutlined />} onClick={() => openModal(r)} />
        <Popconfirm title="حذف؟" onConfirm={() => handleDelete(r._id)}><Button type="text" danger icon={<DeleteOutlined />} /></Popconfirm>
      </Space>
    )},
  ];

  return (
    <div>
      <PageHeader
        title="لوحة الإعلانات"
        subtitle="تسجيل إعلانات القضايا وبيانات المعلن إليه وتواريخ التسليم والجلسات"
        onAdd={() => openModal()}
        addLabel="إضافة +"
        searchValue={search}
        onSearch={setSearch}
        searchPlaceholder="بحث..."
      />
      {/* فلتر حسب الموكل */}
      <div style={{ marginBottom: 12, display: 'flex', alignItems: 'center', gap: 8 }}>
        <UserOutlined style={{ color: '#C9A227' }} />
        <span style={{ fontSize: 13, color: '#555', whiteSpace: 'nowrap' }}>فلتر حسب الموكل:</span>
        <Select
          allowClear
          showSearch
          placeholder="كل الموكلين"
          optionFilterProp="children"
          value={customerFilter}
          onChange={(val) => setCustomerFilter(val)}
          options={customers.map((c: any) => ({ value: c._id, label: c.name }))}
          style={{ minWidth: 220 }}
        />
      </div>
      <Table columns={columns} dataSource={filtered} rowKey="_id" loading={loading} size="small" pagination={{ pageSize: 10 }} />

      <AppModal
        title={editing ? 'تعديل إعلان' : 'إضافة إعلان جديد'}
        subtitle="أدخل بيانات الإعلان وبيانات المستلم والمرفقات"
        icon={<NotificationOutlined />}
        iconColor="#2980b9"
        iconColorTo="#3498db"
        open={modalOpen}
        onOk={handleSubmit}
        onCancel={() => setModalOpen(false)}
        confirmLoading={submitting}
        okText="حفظ"
        cancelText="إلغاء"
        width={820}
      >
        <Form form={form} layout="vertical">
          {/* Section 1: بيانات القضية والإعلان */}
          <FormSection icon={<NotificationOutlined />} title="بيانات القضية والإعلان">
            <Row gutter={16}>
              <Col span={12}>
                <Form.Item name="customerId" label="فلتر بالموكل">
                  <Select
                    showSearch
                    placeholder="اختر موكلاً لتصفية القضايا"
                    optionFilterProp="children"
                    value={selectedCustomerId}
                    onChange={(val) => {
                      setSelectedCustomerId(val);
                      form.setFieldsValue({ caseId: undefined });
                    }}
                    options={customers.map((c: any) => ({ value: c._id, label: c.name }))}
                    suffixIcon={<UserOutlined />}
                  />
                </Form.Item>
              </Col>
              <Col span={12}>
                <Form.Item name="caseId" label="القضية (اكتب للبحث)">
                  <Select
                    showSearch
                    placeholder="ابحث عن قضية"
                    optionFilterProp="children"
                    onChange={handleCaseChange}
                    options={filteredCases.map((c: any) => ({ value: c._id, label: `${c.caseNumber} - ${getCaseCustomerId(c) ? customerNameMap.get(getCaseCustomerId(c)!) || '' : ''}` }))}
                  />
                </Form.Item>
              </Col>
            </Row>
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item name="courtId" label="المحكمة" rules={[{ required: true, message: 'يرجى اختيار المحكمة' }]}>
                  <Select showSearch optionFilterProp="children" placeholder="اختر المحكمة" options={courts.map((c: any) => ({ value: c._id, label: c.name }))} />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="bailiffName" label="اسم المحضر" rules={[{ required: true, message: 'يرجى إدخال اسم المحضر' }]}>
                  <Input placeholder="اسم المحضر" prefix={<UserOutlined />} />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="announcementTypeId" label="نوع الإعلان" rules={[{ required: true, message: 'يرجى اختيار نوع الإعلان' }]}>
                  <Select showSearch optionFilterProp="children" placeholder="اختر نوع الإعلان" options={annTypes.map((t: any) => ({ value: t._id, label: t.name }))} />
                </Form.Item>
              </Col>
            </Row>
          </FormSection>

          {/* Section 2: بيانات المُعلَن إليه والتواريخ */}
          <FormSection icon={<TeamOutlined />} title="بيانات المُعلَن إليه والتواريخ">
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item name="announcementNumber" label="رقم الإعلان" rules={[{ required: true, message: 'يرجى إدخال رقم الإعلان' }]}>
                  <Input placeholder="رقم الإعلان" dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="recipientName" label="المُعلَن إليه (الاسم)" rules={[{ required: true, message: 'يرجى إدخال اسم المستلم' }]}>
                  <Input placeholder="اسم المستلم" prefix={<UserOutlined />} />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="recipientAddress" label="عنوان المُعلَن إليه" rules={[{ required: true, message: 'يرجى إدخال عنوان المستلم' }]}>
                  <Input placeholder="عنوان المستلم" prefix={<EnvironmentOutlined />} />
                </Form.Item>
              </Col>
            </Row>
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item name="deliveryDate" label="تاريخ تسليم الإعلان">
                  <Input type="date" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="receiptDate" label="تاريخ استلام الإعلان">
                  <Input type="date" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="sessionDate" label="تاريخ الجلسة المُعلَن بها">
                  <Input type="date" />
                </Form.Item>
              </Col>
            </Row>
          </FormSection>

          {/* Section 3: الموضوع والمرفقات */}
          <FormSection icon={<FileTextOutlined />} title="الموضوع والمرفقات">
            <Form.Item name="subject" label="موضوع الإعلان" rules={[{ required: true, message: 'يرجى إدخال الموضوع' }]}>
              <Input.TextArea rows={3} placeholder="موضوع الإعلان" />
            </Form.Item>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
              <PaperClipOutlined style={{ color: '#C9A227' }} />
              <span style={{ fontWeight: 600, fontSize: 13, color: '#2c3e50' }}>المرفقات</span>
            </div>
            <Upload.Dragger
              fileList={fileList}
              onChange={({ fileList: newList }) => setFileList(newList)}
              beforeUpload={() => false}
              multiple
              maxCount={10}
              onRemove={(file) => setFileList(prev => prev.filter(f => f.uid !== file.uid))}
              style={{ background: 'transparent', borderColor: '#e0e0e0' }}
            >
              <p style={{ margin: 0, fontSize: 13, color: '#999' }}>
                <UploadOutlined style={{ fontSize: 24, color: '#C9A227', marginBottom: 4 }} />
                <br />
                اضغط أو اسحب الملفات هنا
              </p>
            </Upload.Dragger>
          </FormSection>
        </Form>
      </AppModal>
    </div>
  );
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import { Table, Switch, Typography, Modal, Form, Input, Select, message, Row, Col, Upload, Button } from 'antd';
import type { UploadFile } from 'antd/es/upload/interface';
import {
  PlusOutlined, FileTextOutlined, SaveOutlined, UploadOutlined,
  PaperClipOutlined, CalendarOutlined, AuditOutlined, UserOutlined,
  BankOutlined, NumberOutlined, ClockCircleOutlined, DeleteOutlined,
  CloseOutlined, SearchOutlined, EnvironmentOutlined,
} from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';
import api from '../api/client';
import { PageHeader } from '../components/PageHeader';
import { AppModal, FormSection } from '../components/AppModal';

const { Text, Title } = Typography;

const sessionsApi = createCrudApi('/sessions');
const casesApi = createCrudApi('/cases');
const courtsApi = createCrudApi('/courts');
const customersApi = createCrudApi('/customers');
const sessionDocsApi = createCrudApi('/session-documents');

const ampmOptions = [
  { value: 'صباحاً', label: 'صباحاً' },
  { value: 'مساءً', label: 'مساءً' },
];

const sessionTypeOptions = [
  { value: 'جلسة أولى', label: 'جلسة أولى' },
  { value: 'جلسة نظر', label: 'جلسة نظر' },
  { value: 'جلسة مرافعة', label: 'جلسة مرافعة' },
  { value: 'جلسة حكم', label: 'جلسة حكم' },
  { value: 'جلسة إعلان', label: 'جلسة إعلان' },
  { value: 'جلسة تأجيل', label: 'جلسة تأجيل' },
];

export default function Sessions() {
  const [sessions, setSessions] = useState<any[]>([]);
  const [cases, setCases] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [upcomingOnly, setUpcomingOnly] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);
  const [selectedRowKeys, setSelectedRowKeys] = useState<any[]>([]);
  const [clientFilter, setClientFilter] = useState<string | undefined>(undefined);
  const [fileList, setFileList] = useState<UploadFile[]>([]);
  const [sessionNumber, setSessionNumber] = useState(1);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [sessRes, caseRes, courtRes, custRes] = await Promise.all([
        sessionsApi.getAll(), casesApi.getAll(), courtsApi.getAll(), customersApi.getAll(),
      ]);
      setSessions(sessRes.data.data || sessRes.data || []);
      setCases(caseRes.data.data || caseRes.data || []);
      setCourts(courtRes.data.data || courtRes.data || []);
      setCustomers(custRes.data.data || custRes.data || []);
    } catch { message.error('حدث خطأ أثناء تحميل البيانات'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  const today = new Date().toISOString().split('T')[0];
  const filtered = upcomingOnly ? sessions.filter(s => (s.sessionDate || '') >= today) : sessions;

  // فلترة القضايا حسب الموكل المختار
  const filteredCases = useMemo(() => {
    if (!clientFilter) return cases;
    return cases.filter(c => c.customerId === clientFilter || c.customerId?._id === clientFilter);
  }, [cases, clientFilter]);

  const openAdd = () => {
    setEditing(null);
    form.resetFields();
    setClientFilter(undefined);
    setFileList([]);
    setSessionNumber(1);
    setModalOpen(true);
  };

  const openEdit = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('يرجى اختيار جلسة للتعديل');
      return;
    }
    const selected = sessions.find((s) => s._id === selectedRowKeys[0]);
    if (!selected) return;
    setEditing(selected);
    // فك التاريخ والوقت وص/م من الحقل المدمج
    const parseDateField = (combined: string) => {
      if (!combined) return { date: '', time: '', ampm: '' };
      const parts = combined.split(' - ');
      const date = parts[0]?.trim() || '';
      const timeAndAmPm = parts[1]?.trim() || '';
      const ampmMatch = timeAndAmPm.match(/(صباحاً|مساءً)/);
      const ampm = ampmMatch ? ampmMatch[0] : '';
      const time = timeAndAmPm.replace(/(صباحاً|مساءً)/, '').trim();
      return { date, time, ampm };
    };
    const sd = parseDateField(selected.sessionDate);
    const nsd = parseDateField(selected.nextSessionDate);
    form.setFieldsValue({
      ...selected,
      caseId: selected.caseId?._id || selected.caseId,
      courtId: selected.courtId?._id || selected.courtId,
      sessionDate: sd.date,
      sessionTime: sd.time,
      sessionAmPm: sd.ampm,
      nextSessionDate: nsd.date,
      nextSessionTime: nsd.time,
      nextSessionAmPm: nsd.ampm,
    });
    setFileList([]);
    setModalOpen(true);
  };

  // حساب رقم الجلسة التلقائي عند اختيار القضية
  const handleCaseChange = (caseId: string) => {
    const caseSessions = sessions.filter(s => s.caseId === caseId || s.caseId?._id === caseId);
    const nextNum = caseSessions.length + 1;
    setSessionNumber(nextNum);
    form.setFieldValue('sessionNumber', nextNum);

    // ملء المحكمة تلقائياً من القضية
    const selectedCase = cases.find(c => c._id === caseId);
    if (selectedCase?.courtId) {
      form.setFieldValue('courtId', selectedCase.courtId?._id || selectedCase.courtId);
    }
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();

      // دمج التاريخ والوقت وص/م في حقل واحد
      const formatDateField = (date: string, time: string, ampm: string) => {
        if (!date) return '';
        let result = date;
        if (time) result += ` - ${time}`;
        if (ampm) result += ` ${ampm}`;
        return result;
      };

      const payload = {
        ...values,
        sessionDate: formatDateField(values.sessionDate, values.sessionTime, values.sessionAmPm),
        nextSessionDate: formatDateField(values.nextSessionDate, values.nextSessionTime, values.nextSessionAmPm),
      };
      delete payload.sessionTime;
      delete payload.sessionAmPm;
      delete payload.nextSessionTime;
      delete payload.nextSessionAmPm;

      setSubmitting(true);
      let sessionId: string;

      if (editing?._id) {
        await sessionsApi.update(editing._id, payload);
        sessionId = editing._id;
        message.success('تم تحديث الجلسة');
      } else {
        const res = await sessionsApi.create(payload);
        sessionId = res.data.data?._id || res.data._id;
        message.success('تم إضافة الجلسة');
      }

      // رفع المرفقات
      if (fileList.length > 0 && sessionId) {
        for (const file of fileList) {
          const rawFile = file.originFileObj;
          if (!rawFile) continue;
          const uploadRes = await fileApi.upload(rawFile);
          const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
          const fileName = uploadRes.data.data?.fileName || rawFile.name;
          await api.post('/session-documents', {
            caseSessionId: sessionId,
            documentName: rawFile.name,
            fileId,
            fileName,
            documentType: 'مرفق جلسة',
          });
        }
        message.success(`تم رفع ${fileList.length} مرفق`);
      }

      setModalOpen(false);
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('يرجى اختيار جلسة للحذف');
      return;
    }
    Modal.confirm({
      title: 'هل أنت متأكد من حذف هذه الجلسة؟',
      okText: 'نعم',
      cancelText: 'إلغاء',
      okButtonProps: { style: { background: '#c0392b', borderColor: '#c0392b' } },
      onOk: async () => {
        try {
          await Promise.all(selectedRowKeys.map((key) => sessionsApi.delete(key)));
          message.success('تم حذف الجلسة');
          setSelectedRowKeys([]);
          fetchData();
        } catch { message.error('حدث خطأ أثناء الحذف'); }
      },
    });
  };

  const columns = [
    { title: 'رقم الجلسة', dataIndex: 'sessionNumber', width: 80 },
    { title: 'القضية', dataIndex: 'caseNumber', width: 80 },
    { title: 'الموكل', dataIndex: 'customerName', width: 100, ellipsis: true },
    { title: 'التاريخ', dataIndex: 'sessionDate', width: 140 },
    { title: 'المحكمة', dataIndex: 'courtName', ellipsis: true },
    { title: 'القاعة', dataIndex: 'hallNumber', width: 60 },
    { title: 'الموضوع', dataIndex: 'subject', ellipsis: true },
    { title: 'النوع', dataIndex: 'sessionType', ellipsis: true },
    { title: 'القرار', dataIndex: 'sessionDecision', ellipsis: true },
    { title: 'الجلسة القادمة', dataIndex: 'nextSessionDate', width: 140 },
  ];

  return (
    <div>
      <PageHeader
        title="إدارة جلسات المحاكم"
        subtitle="تسجيل جلسات القضايا ومواعيدها وقراراتها والجلسة القادمة"
        onAdd={openAdd}
        onEdit={openEdit}
        onDelete={handleDelete}
        addLabel="إضافة +"
      />
      <div style={{ marginBottom: 10 }}>
        <Text>الجلسات القادمة فقط: </Text>
        <Switch checked={upcomingOnly} onChange={setUpcomingOnly} />
      </div>
      <Table
        columns={columns}
        dataSource={filtered}
        rowKey="_id"
        loading={loading}
        size="small"
        rowSelection={{
          selectedRowKeys,
          onChange: (keys) => setSelectedRowKeys(keys),
        }}
        pagination={{ pageSize: 10 }}
      />

      <AppModal
        title={editing ? 'تعديل جلسة' : 'إضافة جلسة جديدة'}
        subtitle="أدخل بيانات الجلسة والمعلومات المطلوبة"
        icon={<CalendarOutlined />}
        iconColor="#2980b9"
        iconColorTo="#3498db"
        open={modalOpen}
        onOk={handleSubmit}
        onCancel={() => setModalOpen(false)}
        confirmLoading={submitting}
        okText="حفظ"
        cancelText="إلغاء"
        width={820}
      >
        <Form form={form} layout="vertical">
          {/* القسم 1: بيانات القضية */}
          <FormSection icon={<FileTextOutlined />} title="بيانات القضية">
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item label="فلتر بالموكل">
                  <Select
                    allowClear
                    placeholder="اختر موكلاً للتصفية"
                    optionFilterProp="children"
                    options={customers.map((c: any) => ({ value: c._id, label: c.name }))}
                    suffixIcon={<UserOutlined />}
                    value={clientFilter}
                    onChange={(val) => setClientFilter(val)}
                    style={{ width: '100%' }}
                  />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="القضية" name="caseId" rules={[{ required: true, message: 'يرجى اختيار القضية' }]}>
                  <Select
                    showSearch
                    placeholder="اكتب للبحث"
                    optionFilterProp="children"
                    options={filteredCases.map((c: any) => ({
                      value: c._id,
                      label: `${c.caseNumber}`,
                    }))}
                    suffixIcon={<SearchOutlined />}
                    onChange={handleCaseChange}
                  />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="المحكمة" name="courtId" rules={[{ required: true, message: 'يرجى اختيار المحكمة' }]}>
                  <Select
                    showSearch
                    placeholder="اختر المحكمة"
                    optionFilterProp="children"
                    options={courts.map((c: any) => ({ value: c._id, label: c.name }))}
                    suffixIcon={<BankOutlined />}
                  />
                </Form.Item>
              </Col>
            </Row>
          </FormSection>

          {/* القسم 2: بيانات الجلسة الحالية */}
          <FormSection icon={<CalendarOutlined />} title="بيانات الجلسة الحالية">
            <Row gutter={16}>
              <Col span={6}>
                <Form.Item name="sessionNumber" label="رقم الجلسة" rules={[{ required: true, message: 'مطلوب' }]}>
                  <Input type="number" dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={6}>
                <Form.Item name="rollNumber" label="رقم الرول">
                  <Input placeholder="رقم الرول" dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={6}>
                <Form.Item name="hallNumber" label="رقم القاعة">
                  <Input placeholder="رقم القاعة" dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={6}>
                <Form.Item name="sessionType" label="نوع الجلسة" rules={[{ required: true, message: 'مطلوب' }]}>
                  <Select placeholder="اختر النوع" options={sessionTypeOptions} />
                </Form.Item>
              </Col>
            </Row>
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item name="sessionDate" label="تاريخ الجلسة" rules={[{ required: true, message: 'مطلوب' }]}>
                  <Input type="date" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="sessionTime" label="وقت الجلسة">
                  <Input type="time" dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="sessionAmPm" label="ص/م">
                  <Select placeholder="اختر" options={ampmOptions} />
                </Form.Item>
              </Col>
            </Row>
          </FormSection>

          {/* القسم 3: نتيجة الجلسة */}
          <FormSection icon={<AuditOutlined />} title="نتيجة الجلسة">
            <Form.Item name="subject" label="موضوع الجلسة" rules={[{ required: true, message: 'مطلوب' }]}>
              <Input.TextArea rows={2} placeholder="موضوع الجلسة" />
            </Form.Item>
            <Form.Item name="sessionDecision" label="قرار الجلسة" rules={[{ required: true, message: 'مطلوب' }]}>
              <Input.TextArea rows={2} placeholder="قرار الجلسة" />
            </Form.Item>
          </FormSection>

          {/* القسم 4: الجلسة القادمة (اختياري) */}
          <FormSection icon={<CalendarOutlined />} title="الجلسة القادمة (اختياري)">
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item name="nextSessionDate" label="تاريخ الجلسة القادمة">
                  <Input type="date" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="nextSessionTime" label="وقت الجلسة القادمة">
                  <Input type="time" dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item name="nextSessionAmPm" label="ص/م">
                  <Select placeholder="اختر" options={ampmOptions} />
                </Form.Item>
              </Col>
            </Row>
          </FormSection>

          {/* القسم 5: ملاحظات ومرفقات */}
          <FormSection icon={<PaperClipOutlined />} title="ملاحظات ومرفقات">
            <Form.Item name="notes" label="ملاحظات" rules={[{ required: true, message: 'مطلوب' }]}>
              <Input.TextArea rows={2} placeholder="ملاحظات إضافية" />
            </Form.Item>
            <div style={{
              background: '#fff', border: '1px dashed #d9d9d9',
              borderRadius: 8, padding: '12px 16px', marginBottom: 8,
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                <UploadOutlined style={{ color: '#C9A227' }} />
                <span style={{ fontWeight: 600, fontSize: 13, color: '#2c3e50' }}>المرفقات</span>
                <span style={{ fontSize: 11, color: '#999' }}>(مستندات، صور، محاضر...)</span>
              </div>
              <Upload.Dragger
                fileList={fileList}
                onChange={({ fileList: newList }) => setFileList(newList)}
                beforeUpload={() => false}
                multiple
                maxCount={10}
                onRemove={(file) => setFileList(prev => prev.filter(f => f.uid !== file.uid))}
                style={{ background: 'transparent', borderColor: '#e0e0e0' }}
              >
                <p style={{ margin: 0, fontSize: 13, color: '#999' }}>
                  <UploadOutlined style={{ fontSize: 24, color: '#C9A227', marginBottom: 4 }} />
                  <br />
                  اضغط أو اسحب الملفات هنا
                </p>
              </Upload.Dragger>
            </div>
          </FormSection>
        </Form>
      </AppModal>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Table, Modal, Form, Input, Select, message, Row, Col, Upload, Button, Typography } from 'antd';
import type { UploadFile } from 'antd/es/upload/interface';
import {
  PlusOutlined, TeamOutlined, FileTextOutlined, SaveOutlined,
  UploadOutlined, PaperClipOutlined, FolderOpenOutlined,
  UserOutlined, SearchOutlined, BankOutlined, CalendarOutlined,
  NumberOutlined, FlagOutlined, EnvironmentOutlined, DeleteOutlined,
} from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';
import api from '../api/client';
import { PageHeader } from '../components/PageHeader';
import { AppModal, FormSection } from '../components/AppModal';

const { Title, Text } = Typography;

const casesApi = createCrudApi('/cases');
const customersApi = createCrudApi('/customers');
const courtsApi = createCrudApi('/courts');
const caseTypesApi = createCrudApi('/case-types');
const caseDocsApi = createCrudApi('/case-documents');

export default function Cases() {
  const navigate = useNavigate();
  const [cases, setCases] = useState<any[]>([]);
  const [customers, setCustomers] = useState<any[]>([]);
  const [courts, setCourts] = useState<any[]>([]);
  const [caseTypes, setCaseTypes] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [submitting, setSubmitting] = useState(false);
  const [selectedRowKeys, setSelectedRowKeys] = useState<any[]>([]);
  const [fileList, setFileList] = useState<UploadFile[]>([]);

  const fetchAll = useCallback(async () => {
    setLoading(true);
    try {
      const [casesRes, custRes, courtsRes, typesRes] = await Promise.all([
        casesApi.getAll(), customersApi.getAll(), courtsApi.getAll(), caseTypesApi.getAll(),
      ]);
      setCases(casesRes.data.data || casesRes.data || []);
      setCustomers(custRes.data.data || custRes.data || []);
      setCourts(courtsRes.data.data || courtsRes.data || []);
      setCaseTypes(typesRes.data.data || typesRes.data || []);
    } catch { message.error('حدث خطأ أثناء تحميل البيانات'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const filtered = cases.filter((c: any) => {
    if (!search) return true;
    const q = search.toLowerCase();
    return (c.caseNumber || '').includes(q) || (c.customerName || '').toLowerCase().includes(q);
  });

  const openAdd = () => {
    setEditing(null);
    form.resetFields();
    setFileList([]);
    setModalOpen(true);
  };

  const openEdit = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('يرجى اختيار قضية للتعديل');
      return;
    }
    const selected = cases.find((c) => c._id === selectedRowKeys[0]);
    if (!selected) return;
    setEditing(selected);
    form.setFieldsValue({
      ...selected,
      customerId: selected.customerId?._id || selected.customerId,
      courtId: selected.courtId?._id || selected.courtId,
      caseTypeId: selected.caseTypeId?._id || selected.caseTypeId,
    });
    setFileList([]);
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setSubmitting(true);
      let caseId: string;

      if (editing?._id) {
        await casesApi.update(editing._id, values);
        caseId = editing._id;
        message.success('تم تحديث القضية');
      } else {
        const res = await casesApi.create(values);
        caseId = res.data.data?._id || res.data._id;
        message.success('تم إضافة القضية');
      }

      // رفع المرفقات
      if (fileList.length > 0 && caseId) {
        for (const file of fileList) {
          const rawFile = file.originFileObj;
          if (!rawFile) continue;
          const uploadRes = await fileApi.upload(rawFile);
          const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
          const fileName = uploadRes.data.data?.fileName || rawFile.name;
          await caseDocsApi.create({
            caseId,
            documentName: rawFile.name,
            documentType: 'مرفق',
            fileId,
            fileName,
            notes: '',
          });
        }
        message.success(`تم رفع ${fileList.length} مرفق`);
      }

      setModalOpen(false);
      fetchAll();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setSubmitting(false); }
  };

  const handleDelete = () => {
    if (selectedRowKeys.length === 0) {
      message.warning('يرجى اختيار قضية للحذف');
      return;
    }
    Modal.confirm({
      title: 'هل أنت متأكد من حذف هذه القضية؟',
      okText: 'نعم',
      cancelText: 'إلغاء',
      okButtonProps: { style: { background: '#c0392b', borderColor: '#c0392b' } },
      onOk: async () => {
        try {
          await Promise.all(selectedRowKeys.map((key) => casesApi.delete(key)));
          message.success('تم حذف القضية');
          setSelectedRowKeys([]);
          fetchAll();
        } catch { message.error('حدث خطأ أثناء الحذف'); }
      },
    });
  };

  const columns = [
    { title: 'رقم القضية', dataIndex: 'caseNumber', width: 80, render: (t: string, r: any) => <a onClick={() => navigate(`/cases/${r._id}`)}>{t}</a> },
    { title: 'السنة', dataIndex: 'caseYear', width: 60 },
    { title: 'الموكل', dataIndex: 'customerName', ellipsis: true },
    { title: 'صفة الموكل', dataIndex: 'clientCapacity', ellipsis: true },
    { title: 'الخصم', dataIndex: 'opponentName', ellipsis: true },
    { title: 'صفة الخصم', dataIndex: 'opponentCapacity', ellipsis: true },
    { title: 'المحكمة', dataIndex: 'courtName', ellipsis: true },
    { title: 'الدائرة', dataIndex: 'circuitNumber', width: 60 },
    { title: 'نوع القضية', dataIndex: 'caseTypeName', ellipsis: true },
    { title: 'الموضوع', dataIndex: 'caseSubject', ellipsis: true },
    { title: 'تاريخ الإضافة', dataIndex: 'createdDate', width: 100, render: (v: string) => v ? new Date(v).toLocaleDateString('en-GB') : '' },
  ];

  const currentYear = new Date().getFullYear();
  const yearOptions = Array.from({ length: 10 }, (_, i) => ({ value: currentYear - i, label: String(currentYear - i) }));

  return (
    <div>
      <PageHeader
        title="إدارة ملفات القضايا"
        subtitle="تسجيل قضايا الموكلين وربطها بالمحاكم والدوائر"
        onAdd={openAdd}
        onEdit={openEdit}
        onDelete={handleDelete}
        searchValue={search}
        onSearch={setSearch}
        addLabel="إضافة +"
      />
      <Table
        columns={columns}
        dataSource={filtered}
        rowKey="_id"
        loading={loading}
        size="small"
        rowSelection={{
          selectedRowKeys,
          onChange: (keys) => setSelectedRowKeys(keys),
        }}
        pagination={{ pageSize: 10 }}
      />

      <AppModal
        title={editing ? 'تعديل قضية' : 'إضافة قضية جديدة'}
        subtitle="أدخل بيانات القضية وأطرافها"
        icon={<FolderOpenOutlined />}
        iconColor="#27ae60"
        iconColorTo="#2ecc71"
        open={modalOpen}
        onOk={handleSubmit}
        onCancel={() => setModalOpen(false)}
        confirmLoading={submitting}
        okText="حفظ"
        cancelText="إلغاء"
        width={820}
      >
        <Form form={form} layout="vertical">
          {/* Section 1: Case Parties */}
          <FormSection icon={<TeamOutlined />} title="أطراف القضية">
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item label="الموكل" name="customerId" rules={[{ required: true, message: 'يرجى اختيار الموكل' }]}>
                  <Select
                    showSearch
                    placeholder="اختر الموكل"
                    optionFilterProp="children"
                    options={customers.map((c: any) => ({ value: c._id, label: c.name }))}
                    suffixIcon={<UserOutlined />}
                    dropdownRender={(menu) => (
                      <>
                        {menu}
                        <div style={{ padding: 4, borderTop: '1px solid #e8e8e8', marginTop: 4 }}>
                          <Button type="text" icon={<PlusOutlined />} style={{ color: '#27ae60' }} onClick={() => navigate('/customers')} block>
                            إضافة موكل جديد
                          </Button>
                        </div>
                      </>
                    )}
                  />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="صفة الموكل" name="clientCapacity">
                  <Input placeholder="صفة الموكل" prefix={<FlagOutlined />} />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="نوع القضية" name="caseTypeId" rules={[{ required: true, message: 'يرجى اختيار نوع القضية' }]}>
                  <Select
                    showSearch
                    placeholder="اختر نوع القضية"
                    optionFilterProp="children"
                    options={caseTypes.map((c: any) => ({ value: c._id, label: c.name }))}
                    dropdownRender={(menu) => (
                      <>
                        {menu}
                        <div style={{ padding: 4, borderTop: '1px solid #e8e8e8', marginTop: 4 }}>
                          <Button type="text" icon={<PlusOutlined />} style={{ color: '#8e44ad' }} onClick={() => navigate('/settings/case-types')} block>
                            إضافة نوع قضية
                          </Button>
                        </div>
                      </>
                    )}
                  />
                </Form.Item>
              </Col>
            </Row>
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item label="اسم الخصم" name="opponentName" rules={[{ required: true, message: 'يرجى إدخال اسم الخصم' }]}>
                  <Input placeholder="اسم الخصم" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="صفة الخصم" name="opponentCapacity">
                  <Input placeholder="صفة الخصم" prefix={<FlagOutlined />} />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="المحكمة المختصة" name="courtId" rules={[{ required: true, message: 'يرجى اختيار المحكمة' }]}>
                  <Select
                    showSearch
                    placeholder="اختر المحكمة"
                    optionFilterProp="children"
                    options={courts.map((c: any) => ({ value: c._id, label: c.name }))}
                    suffixIcon={<BankOutlined />}
                    dropdownRender={(menu) => (
                      <>
                        {menu}
                        <div style={{ padding: 4, borderTop: '1px solid #e8e8e8', marginTop: 4 }}>
                          <Button type="text" icon={<PlusOutlined />} style={{ color: '#e67e22' }} onClick={() => navigate('/settings/courts')} block>
                            إضافة محكمة
                          </Button>
                        </div>
                      </>
                    )}
                  />
                </Form.Item>
              </Col>
            </Row>
          </FormSection>

          {/* Section 2: Case Data */}
          <FormSection icon={<FileTextOutlined />} title="بيانات القضية">
            <Row gutter={16}>
              <Col span={8}>
                <Form.Item label="رقم الدائرة" name="circuitNumber">
                  <Input placeholder="رقم الدائرة" prefix={<NumberOutlined />} dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="رقم القضية" name="caseNumber" rules={[{ required: true, message: 'يرجى إدخال رقم القضية' }]}>
                  <Input placeholder="رقم القضية" prefix={<NumberOutlined />} dir="ltr" />
                </Form.Item>
              </Col>
              <Col span={8}>
                <Form.Item label="السنة" name="caseYear" rules={[{ required: true, message: 'يرجى اختيار السنة' }]}>
