          <Button type="text" size="small" icon={<EditOutlined />} onClick={() => openEdit(r)} title="تعديل" style={{ color: '#f39c12' }} />
          <Popconfirm title="حذف؟" onConfirm={() => handleDelete(r._id)}>
            <Button type="text" size="small" danger icon={<DeleteOutlined />} title="حذف" />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <div>
      <PageHeader
        title="قوالب المستندات"
        subtitle="إدارة القوالب والمستندات الجاهزة"
        onAdd={openAdd}
        addLabel="رفع قالب"
      />

      {/* شريط البحث والفلترة */}
      <div style={{
        marginBottom: 12,
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        flexWrap: 'wrap',
      }}>
        <Input
          placeholder="بحث بالاسم..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}
          allowClear
          style={{ maxWidth: 220 }}
        />
        <Select
          allowClear
          showSearch
          placeholder="التصنيف"
          optionFilterProp="children"
          value={categoryFilter}
          onChange={(val) => setCategoryFilter(val)}
          options={categoryOptions}
          suffixIcon={<FilterOutlined />}
          style={{ minWidth: 140 }}
        />
        <Select
          allowClear
          showSearch
          placeholder="الصيغة"
          optionFilterProp="children"
          value={formatFilter}
          onChange={(val) => setFormatFilter(val)}
          options={formatOptions}
          suffixIcon={<FilterOutlined />}
          style={{ minWidth: 120 }}
        />
      </div>

      <Table columns={columns} dataSource={filtered} rowKey="_id" loading={loading} size="small" pagination={{ pageSize: 10 }} />

      <AppModal
        title={editing ? 'تعديل قالب مستند' : 'رفع قالب مستند'}
        subtitle="أدخل بيانات المستند وارفع الملف"
        icon={<FolderOpenOutlined />}
        iconColor="#8e44ad"
        iconColorTo="#9b59b6"
        open={modalOpen}
        onOk={handleSubmit}
        onCancel={() => setModalOpen(false)}
        confirmLoading={uploading}
        okText={editing ? 'حفظ التعديلات' : 'رفع'}
        cancelText="إلغاء"
        okColor="#8e44ad"
        width={640}
      >

        <Form form={form} layout="vertical">
          {/* اختيار ملف */}
          <div style={{
            background: '#fafbfc',
            border: '1px dashed #d9d9d9',
            borderRadius: 10,
            padding: '12px 16px',
            marginBottom: 16,
