              {editing && <span style={{ fontSize: 11, color: '#999' }}>(اتركه فارغاً للاحتفاظ بالملف الحالي)</span>}
              {!editing && <span style={{ fontSize: 11, color: '#999' }}>(PDF, Word, صور...)</span>}
            </div>
            <Form.Item
              name="file"
              rules={editing ? [] : [{ required: true, message: 'يرجى اختيار ملف' }]}
