      key: 'identityNumber',
      render: (v: string) => v || '—',
    },
    {
      title: 'العنوان',
      dataIndex: 'address',
      key: 'address',
      render: (v: string) => v || '—',
    },
    {
      title: 'الملاحظات',
      dataIndex: 'notes',
      key: 'notes',
      render: (v: string) => v || '—',
      ellipsis: true,
    },
