        open={modalOpen}
        onOk={handleSubmit}
        onCancel={() => setModalOpen(false)}
        confirmLoading={uploading}
        okText={editing ? 'حفظ التعديلات' : 'رفع'}
        cancelText="إلغاء"
        okColor="#8e44ad"
        width={640}
      >

        <Form form={form} layout="vertical">
          {/* اختيار ملف */}
          <div style={{
